"""Put RenderCV's own HTML and Markdown on the site, whole and unchanged, and
list cv.yaml's profiles with the addresses RenderCV gives them.

Run after .github/scripts/rendercv-render.py. Reads the HTML RenderCV
generated and writes everything inside its <article class="markdown-body">
to _includes/rendercv.html, which index.html includes. Copies the Markdown
RenderCV generated beside it to _includes/rendercv.md, which index.html.md
and llms-full.txt include. Writes each of cv.yaml's social_networks and
custom_connections, with its address as RenderCV makes it, to _profiles.yml,
which Jekyll reads as site.data._profiles (_config.yml's data_dir) and the
rel="me" links, sameAs and llms.txt list. The deploy workflow
(.github/workflows/jekyll-gh-pages.yml) runs both on every build; the files
are not committed, so run them yourself before building the site locally.

Usage: python3 .github/scripts/rendercv-include.py FOLDER (rendercv-render.py's)
"""

import re
import sys
from pathlib import Path

from rendercv.schema.rendercv_model_builder import build_rendercv_dictionary_and_model
from ruamel.yaml import YAML

folder = Path(sys.argv[1])
root = Path(__file__).resolve().parents[2]
includes = root / "_includes"

# RenderCV puts the CV inside <article class="markdown-body">
source = (folder / "cv.html").read_text(encoding="utf-8")
article = re.search(r'<article class="markdown-body">(.*?)</article>', source, re.S)
if not article:
    sys.exit("No <article class=\"markdown-body\"> in RenderCV's HTML")
body = article.group(1)

target = includes / "rendercv.html"
target.write_text(
    "{%- comment -%} Generated by .github/scripts/rendercv-include.py from RenderCV's "
    "HTML. Do not edit; edit cv.yaml and run RenderCV again {%- endcomment %}\n"
    # raw: RenderCV's text is shown as written, never read as Liquid
    + "{% raw %}\n"
    + body.strip()
    + "\n{% endraw %}\n",
    encoding="utf-8",
)
print(f"Wrote {target}")

markdown = (folder / "cv.md").read_text(encoding="utf-8")
target = includes / "rendercv.md"
target.write_text(
    "{% raw %}" + markdown.strip() + "{% endraw %}\n",
    encoding="utf-8",
)
print(f"Wrote {target}")

# RenderCV's own model of cv.yaml, the same one it renders from
cv_path = root / "cv.yaml"
_, model = build_rendercv_dictionary_and_model(cv_path.read_text(encoding="utf-8"), input_file_path=cv_path)
profiles = [{"name": profile.network, "url": profile.url} for profile in model.cv.social_networks or []]
profiles += [
    {"name": profile.placeholder, "url": str(profile.url)}
    for profile in model.cv.custom_connections or []
    if profile.url is not None
]
target = root / "_profiles.yml"
with target.open("w", encoding="utf-8") as file:
    YAML().dump(profiles, file)
print(f"Wrote {target}")
